    mode: Union[ImportMode, str],
    rootpath: Path,
    consider_namespace_packages: bool,
) -> ModuleType:
    """Import and return a module from the given path, which may be a file or a directory.

    If the path is a directory, it will import the ``__init__`` file.
    """
    mode = ImportMode(mode)
    path = Path(p)

    if not path.exists():
        raise ImportError(path)

